@@ -0,0 +1,11 @@
+export const resolveStaticAssetSrc = (asset) => {
+  if (typeof asset === "string") {
+    return asset;
+  }
+
+  if (asset && typeof asset === "object" && typeof asset.src === "string") {
+    return asset.src;
+  }
+
+  return "";
+};
